True from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    fill = freq.most_common(1)[0][0]
    rail = next(v for v,_ in freq.most_common() if v != fill)
    row_lines = [r for r,row in enumerate(grid) if row.count(rail) > w//2]
    col_lines = [c for c in range(w) if sum(grid[r][c] == rail for r in range(h)) > h//2]
    if len(row_lines) < 2 or len(col_lines) < 2:
        return [row[:] for row in grid]
    out=[]
    for r0,r1 in zip(row_lines,row_lines[1:]):
        line=[]
        for c0,c1 in zip(col_lines,col_lines[1:]):
            corners=[grid[r0][c0],grid[r0][c1],grid[r1][c0],grid[r1][c1]]
            if corners[0] != rail and corners.count(corners[0]) == 4:
                line.append(corners[0])
            else:
                line.append(fill)
        out.append(line)
    while out and all(v==fill for v in out[0]): out.pop(0)
    while out and all(v==fill for v in out[-1]): out.pop()
    while out and all(row[0]==fill for row in out):
        for row in out: row.pop(0)
    while out and all(row[-1]==fill for row in out):
        for row in out: row.pop()
    return out

